"""CPU-only regression checks for conservative dense-person deduplication.

Run with cvat_tools/.venv/Scripts/python.exe cvat_tools/check_people_dedup.py.
--corpus additionally checks the seven inspected source-frame cases using the
saved automatic tracks; it never runs inference or writes annotation data.
"""
from __future__ import annotations

import argparse
import copy
import json
import unittest
from pathlib import Path

from deduplicate_people import deduplicate_people


# Independent visual QA fixtures, not generated by the implementation.
# X13 deliberately keeps 1: 47 includes the wooden table below the visible body.
CONFIRMED = [
    ('X-8', 285, 0, 10, [111.73,305.52,192.5,412.58], [111.21,305.22,211.14,524.14], .4972,.2991,'detector','detector',0),
    ('X-8', 570, 0, 16, [146.34,309.62,189.48,399.94], [108.94,302.95,194.75,411.72], .3418,.8021,'optical_flow','detector',16),
    ('X-8', 949, 16, 22, [107.51,299.4,195.89,412.27], [106.86,299.09,209.65,529.95], .2987,.5093,'optical_flow','optical_flow',22),
    ('X-11',573, 0, 16, [56.22,216.85,129.91,414.89], [51.68,221.51,205.14,524.83], .6926,.2739,'optical_flow','optical_flow',0),
    ('X-11',700, 0, 19, [136.88,198.37,188.64,406.76], [126.09,198.67,206.43,524.64], .5171,.2777,'optical_flow','optical_flow',0),
    ('X-12',316, 0, 6, [104.69,307.87,238.74,421.12], [104.6,307.55,214.74,531.52], .8301,.4822,'optical_flow','optical_flow',0),
    ('X-13',1140,1,47, [142.55,271.42,217.51,366.35], [142.71,271.42,217.46,489.63], .457,.2775,'detector','detector',1),
]

# Distinct real people in X1..5: customer/cashier, and a room person beside a
# glass person. Labels intentionally equal here to challenge geometry alone.
DISTINCT = [
    ('X-1',120,[11.41,215.36,100.15,427.06],[.1,198.65,26.73,289.08],.761,.3924),
    ('X-1',690,[148.6,378.54,280.79,593.93],[143.25,298.33,228.92,414.6],.8267,.7476),
    ('X-2',180,[21.16,218.49,103.79,414.89],[.12,193.25,38.24,294.2],.7615,.3508),
    ('X-3',299,[170.17,386.82,282.57,594.63],[122.4,288.13,222.7,406.88],.8495,.8125),
    ('X-4',1088,[170.72,383.6,273.85,595.06],[116.15,294.45,203.37,418.75],.8223,.78),
    ('X-4',1088,[.13,221.49,51.28,292.93],[45.61,235.41,100.68,368.63],.6661,.5026),
    ('X-5',1072,[173.59,383.87,279.74,593.02],[105.14,293.17,198.9,415.26],.7915,.8315),
    ('X-5',1072,[.15,221.61,51.67,292.26],[38.08,237.18,94.02,327],.3751,.2846),
]


def track(tid, box, score, method='detector', label='person', frames=(0,1,2)):
    return {'original_id':tid,'label':label,'origin':'dynamic_tracking',
            'attributes':{'role':'cashier'},'samples':[
                {'frame':f,'box':list(box),'score':score,'method':method,
                 'outside':False,'occluded':False,'attributes':{}} for f in frames]}


def visible_ids(tracks, frame):
    return {t['original_id'] for t in tracks for s in t['samples']
            if s['frame']==frame and not s.get('outside',False)}


class DedupChecks(unittest.TestCase):
    def test_confirmed_duplicates(self):
        for name,f,a,b,ba,bb,sa,sb,ma,mb,winner in CONFIRMED:
            with self.subTest(video=name,frame=f):
                ts=[track(a,ba,sa,ma,frames=(f,f+1,f+2)),track(b,bb,sb,mb,frames=(f,f+1,f+2))]
                filtered,report=deduplicate_people(ts)
                self.assertEqual(visible_ids(filtered,f),{winner})
                self.assertEqual(report['duplicate_people_samples_removed'],3)

    def test_distinct_people_from_five_videos(self):
        for name,f,a,b,sa,sb in DISTINCT:
            with self.subTest(video=name,frame=f):
                ts=[track(0,a,sa),track(1,b,sb)]
                self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_high_overlap_with_different_head_heights_is_preserved(self):
        ts=[track(0,[100,100,200,400],.92),track(1,[110,180,190,360],.29)]
        self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_different_labels_never_suppress_each_other(self):
        ts=[track(0,[100,100,200,400],.9),track(1,[100,100,200,250],.3,label='reflection')]
        self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_reflections_are_deduplicated_within_their_own_label(self):
        ts=[track(0,[100,100,200,400],.3,label='reflection'),track(1,[100,100,200,250],.8,label='reflection')]
        filtered,report=deduplicate_people(ts)
        self.assertEqual(visible_ids(filtered,0),{1})
        self.assertEqual(report['duplicate_people_removed_by_label'],{'reflection':3})

    def test_hands_are_untouched(self):
        ts=[track(0,[100,100,120,130],.9,label='hand'),track(1,[100,100,120,130],.3,label='hand')]
        self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_single_frame_crossing_is_preserved(self):
        ts=[track(0,[100,100,200,400],.9,frames=(1,)),track(1,[100,100,200,250],.3,frames=(1,))]
        self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_no_size_preference(self):
        for large_score,small_score,winner in ((.9,.3,0),(.3,.9,1)):
            ts=[track(0,[100,100,200,400],large_score),track(1,[100,100,200,250],small_score)]
            self.assertEqual(visible_ids(deduplicate_people(ts)[0],0),{winner})

    def test_ambiguous_confidence_and_two_strong_detections_are_preserved(self):
        for a,b in ((.45,.42),(.95,.7)):
            ts=[track(0,[100,100,200,400],a),track(1,[100,100,200,250],b)]
            self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_nested_input_is_not_mutated_or_aliased(self):
        ts=[track(0,[100,100,200,400],.9),track(1,[100,100,200,250],.3)]
        before=copy.deepcopy(ts)
        filtered,_=deduplicate_people(ts)
        self.assertEqual(ts,before)
        filtered[0]['samples'][0]['box'][0]=999
        filtered[0]['attributes']['role']='changed'
        self.assertEqual(ts,before)

    def test_nonadjacent_evidence_does_not_count_as_a_run(self):
        ts=[track(0,[100,100,200,400],.9,frames=(0,2,4)),track(1,[100,100,200,250],.3,frames=(0,2,4))]
        self.assertEqual(deduplicate_people(ts)[0],ts)

    def test_only_duplicate_frames_are_removed(self):
        ts=[track(0,[100,100,200,400],.9,frames=(0,1,2,3)),track(1,[100,100,200,250],.3,frames=(0,1,2,3))]
        ts[1]['samples'][3]['box']=[250,100,350,250]
        filtered,_=deduplicate_people(ts)
        self.assertEqual(visible_ids(filtered,1),{0})
        self.assertEqual(visible_ids(filtered,3),{0,1})

    def test_fresh_detection_beats_stale_flow_with_similar_score(self):
        stale=track(0,[100,100,200,400],.52,'optical_flow',frames=range(33))
        stale['samples'][0]['method']='detector'
        fresh=track(1,[100,100,200,250],.56,frames=(30,31,32))
        filtered,_=deduplicate_people([stale,fresh])
        self.assertEqual(visible_ids(filtered,30),{1})

    def test_outside_is_not_evidence_and_remains_for_caller_to_rebuild(self):
        ts=[track(0,[100,100,200,400],.9),track(1,[100,100,200,250],.3)]
        for t in ts:
            t['samples'].append(dict(t['samples'][-1],frame=3,outside=True))
        filtered,_=deduplicate_people(ts)
        self.assertEqual(len(filtered),1)
        self.assertTrue(filtered[0]['samples'][-1]['outside'])

    def test_transitive_overlap_does_not_erase_two_survivors(self):
        # B resembles A and C, but A/C have different upper edges.
        ts=[track(0,[100,100,200,250],.9),
            track(1,[100,106,200,250],.4),
            track(2,[100,112,200,250],.25)]
        self.assertEqual(visible_ids(deduplicate_people(ts)[0],0),{0,2})

    def test_missing_or_nonfinite_score_stays(self):
        for score in (None,float('nan')):
            ts=[track(0,[100,100,200,400],.9),track(1,[100,100,200,250],score)]
            self.assertEqual(visible_ids(deduplicate_people(ts)[0],0),{0,1})


def check_corpus():
    root=Path(__file__).resolve().parent
    cache={}
    for name,f,a,b,ba,bb,sa,sb,ma,mb,winner in CONFIRMED:
        if name not in cache:
            auto=json.loads((root/'automatic'/f'{name}.json').read_text())
            tracks=[]
            for t in auto['tracks']:
                if t['label']!='person':continue
                samples=[{'frame':s[0],'box':s[1:5],'outside':s[5],
                          'score':s[7],'method':s[8]} for s in t['samples']]
                tracks.append({'label':'person','original_id':t['id'],'samples':samples})
            cache[name]=deduplicate_people(tracks)
        filtered,report=cache[name]
        present=visible_ids(filtered,f)&{a,b}
        assert present=={winner},(name,f,present,winner)
        print(f'{name} frame {f}: keep {winner}, remove {({a,b}-{winner}).pop()}')
    for name,(_,report) in cache.items():
        print(name,json.dumps(report,sort_keys=True))
    expected={('X-1',120):{0,4,10},('X-1',690):{0,4,12},
              ('X-2',180):{0,2,11},('X-3',299):{0,5,14},
              ('X-4',1088):{0,2,9,13},('X-5',1072):{0,1,11,41}}
    for (name,f),identities in expected.items():
        if name not in cache:
            auto=json.loads((root/'automatic'/f'{name}.json').read_text())
            tracks=[{'label':t['label'],'original_id':t['id'],'samples':[
                {'frame':s[0],'box':s[1:5],'outside':s[5],'score':s[7],'method':s[8]}
                for s in t['samples']]} for t in auto['tracks'] if t['label']=='person']
            cache[name]=deduplicate_people(tracks)
        present=visible_ids(cache[name][0],f)
        assert identities<=present,(name,f,'distinct people were removed',identities-present)
        print(f'{name} frame {f}: preserved {sorted(identities)}')


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--corpus',action='store_true');args=parser.parse_args()
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(DedupChecks))
    if not result.wasSuccessful():raise SystemExit(1)
    if args.corpus:check_corpus()
